// función de cálculo
function interpolarPerfil(horaDecimal, perfil){

    let p1 = perfil[0];
    let p2 = perfil[1];

    for(let i=0;i<perfil.length-1;i++){

        if(horaDecimal >= perfil[i].hora &&
           horaDecimal <= perfil[i+1].hora){

            p1 = perfil[i];
            p2 = perfil[i+1];
            break;
        }
    }

    return p1.valor +
           (horaDecimal-p1.hora)*
           (p2.valor-p1.valor)/
           (p2.hora-p1.hora);
}
