// Función para obtener fecha
function getHora(timestamp) {
    const fecha = new Date(timestamp + "Z");

    const hora = Number(
        fecha.toLocaleString("en-US", {
            timeZone: "America/Argentina/Buenos_Aires",
            hour: "2-digit",
            hour12: false
        })
    );

    const minuto = Number(
        fecha.toLocaleString("en-US", {
            timeZone: "America/Argentina/Buenos_Aires",
            minute: "2-digit"
        })
    );

    const horaDecimal = hora + minuto / 60;
    return horaDecimal;
}

const trafo = {

    // Datos nominales
    potencia_nominal_kVA : 315,
    tension_secundaria_V : 400,
    factor_potencia : 0.92,

    // Parámetros eléctricos
