return null;

const trafo = global.get("trafo");
const carga = msg.payload.carga_pu;

// Corriente nominal
const In =
    (trafo.potencia_nominal_kVA * 1000) /
    (Math.sqrt(3) * trafo.tension_secundaria_V);

// Corriente real
const corriente =
    carga * In;

// Tensión real
const tension_V =
    trafo.tension_secundaria_V *
    (1 - (trafo.regulacion_pct / 100) * carga);

// Potencia aparente
const potencia_kVA =
    carga * trafo.potencia_nominal_kVA;

// Potencia activa
const potencia_kW =
    potencia_kVA * trafo.factor_potencia;

// Agregar resultados al payload
msg.payload.corriente_A = Number(corriente.toFixed(1));
msg.payload.tension_V = Number(tension_V.toFixed(1));
msg.payload.potencia_kVA = Number(potencia_kVA.toFixed(1));
msg.payload.potencia_kW = Number(potencia_kW.toFixed(1));

return msg;

// necesito las variables deltaT_max y constante_termica de "trafo"
const trafo = global.get("trafo");

// Variables de entrada
const corriente = msg.payload.corriente_A;
const temperaturaAmbiente = msg.payload.temperatura_ambiente_C;

// Corriente nominal del transformador
const corrienteNominal =
    (trafo.potencia_nominal_kVA * 1000) /
    (Math.sqrt(3) * trafo.tension_secundaria_V);
// Corriente normalizada (0...1)
const corriente_pu = corriente / corrienteNominal;

// Sobretemperatura máxima
// ΔT = ΔTmax × (I/In)²
const deltaT =
    trafo.deltaT_max_C *
    Math.pow(corriente_pu, 2);

// Temperatura objetivo
const temperaturaObjetivo =
    temperaturaAmbiente + deltaT;

// Recuperar temperatura anterior
let temperaturaAnterior =
    context.get("temperaturaTrafo");
    // Primera ejecución
    if (temperaturaAnterior === undefined) {
        temperaturaAnterior = temperaturaAmbiente;
    }
//------------------------------------------------------
// Modelo térmico de primer orden
// constante térmica
const dt = 15;              // minutos de muestreo
const tau = trafo.constante_termica_min;
const K = 1 - Math.exp(-dt / tau);
node.warn({
    corriente: corriente,
    temperaturaAmbiente: temperaturaAmbiente,
    corrienteNominal: corrienteNominal,
    corriente_pu: corriente_pu,
    deltaT: deltaT,
    temperaturaObjetivo: temperaturaObjetivo,
    temperaturaAnterior: temperaturaAnterior,
    K: K
});

// Tn = Tn-1 + (Tobjetivo - Tn-1) × K
const temperaturaNueva =
    temperaturaAnterior +
    (temperaturaObjetivo - temperaturaAnterior) *
    K;
//------------------------------------------------------
// Guardar estado para la próxima ejecución
context.set("temperaturaTrafo", temperaturaNueva);

//------------------------------------------------------
// Agregar resultados al payload
msg.payload.corriente_pu = Number(corriente_pu.toFixed(3));
msg.payload.deltaT_C = Number(deltaT.toFixed(2));
msg.payload.temperatura_objetivo_C =
    Number(temperaturaObjetivo.toFixed(2));
msg.payload.temperatura_trafo_C =
    Number(temperaturaNueva.toFixed(2));

return msg;

